#!/usr/bin/env python3
from pathlib import Path
import base64, gzip

FILES = {
    "scripts/update_clientid_periods.py": "",
    ".github/workflows/validate-fraud-data.yml": "",
}
for path, payload in FILES.items():
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(gzip.decompress(base64.b64decode(payload)))

Path("scripts/apply_mi_stages_1_2.py").unlink(missing_ok=True)
Path(".github/workflows/apply-mi-stages-1-2.yml").unlink(missing_ok=True)
print("Applied MI antifraud stages 1 and 2 backend changes")
